#!/usr/bin/env bash
# Regenerates server/internal/protocol (Go) and client/src/protocol (TypeScript)
# from protocol/schema. Run via `make protocol`. Output is deterministic.
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$root"

command -v flatc >/dev/null || { echo "flatc not found; install flatbuffers" >&2; exit 1; }

schema=protocol/schema/lush.fbs
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

flatc --go -o "$tmp/go" "$schema"
flatc --ts -o "$tmp/ts" "$schema"

# Replace previously generated files only; hand-written files (tests) stay.
mkdir -p server/internal/protocol client/src/protocol
for f in server/internal/protocol/*.go; do
  [ -e "$f" ] && grep -q "Code generated by the FlatBuffers compiler" "$f" && rm -- "$f"
done
for f in client/src/protocol/*.ts; do
  [ -e "$f" ] && grep -q "automatically generated by the FlatBuffers compiler" "$f" && rm -- "$f"
done

# Normalize flatc version differences (CI installs an older flatc than dev
# machines) so the output is identical everywhere:
#  - drop the Go Finish*Buffer helpers newer flatc adds for every table
#  - drop the eslint-disable header newer flatc adds to TypeScript
#  - drop the ".js" suffix newer flatc adds to relative TypeScript imports
# Then start every TypeScript file with our own header, so generated code
# passes the client's lint and type check without changing client config.
ts_header='/* eslint-disable */
// @ts-nocheck'
perl -0pi -e 's/func Finish(?:SizePrefixed)?\w+Buffer\([^)]*\) \{\n[^}]*\}\n\n//g' "$tmp"/go/protocol/*.go
perl -0pi -e 's{/\* eslint-disable[^\n]*\*/\n\n}{}; s/(from \x27\.[^\x27]*?)\.js\x27/$1\x27/g' "$tmp"/ts/protocol/*.ts
for f in "$tmp"/ts/protocol/*.ts; do
  { echo "$ts_header"; cat "$f"; } > "$f.tmp" && mv "$f.tmp" "$f"
done

cp "$tmp"/go/protocol/*.go server/internal/protocol/
cp "$tmp"/ts/protocol/*.ts client/src/protocol/

# Barrel file so the client imports everything from "./protocol/index.js".
{
  echo "$ts_header"
  echo "// automatically generated by the FlatBuffers compiler, do not modify"
  for f in "$tmp"/ts/protocol/*.ts; do
    n="$(basename "$f" .ts)"
    grep -oE '^export (class|enum) [A-Za-z0-9_]+' "$f" | awk -v n="$n" '{print "export { " $3 " } from \x27./" n "\x27;"}'
  done
} > client/src/protocol/index.ts
